export const k8sActivityCommand = defineCommand({
  description: 'Show the recent activity of a Kubernetes cluster',
  since: null,
  options: {
    limit: defineOption({
      name: 'limit',
      schema: z.coerce.number().int().positive().optional(),
      description: 'Maximum number of events to show',
      placeholder: 'count',
    }),
    org: orgaIdOrNameOption,
    format: humanJsonOutputFormatOption,
  },
  args: [k8sIdOrNameArg],
  async handler(options, clusterIdOrName) {
    const { format, limit, org: orgIdOrName } = options;

    const events = await k8sListActivity(orgIdOrName, clusterIdOrName, limit);

    switch (format) {
      case 'json':
        Logger.printJson(events);
        break;
      case 'human':
      default:
        if (events.length === 0) {
          Logger.println('🔎 No activity found for this cluster');
          return;
        }
        events.forEach((event) => {
          const date = event.date ?? event.createdAt ?? event.timestamp ?? '-';
          const state = event.state ?? event.status;
          const action = event.action ?? event.type ?? event.event ?? '-';
          const details = event.message ?? event.cause;
          const parts = [styleText('grey', String(date)), String(action)];
          if (state != null) parts.push(String(state));
          if (details != null) parts.push(`- ${details}`);
          Logger.println(parts.join(' '));
        });
        break;
    }
  },
});
